parameters.jsonSchema:
{
  "type": "object",
  "properties": {
    "type": {
      "type": "string",
      "enum": ["bug", "task", "feature", "unknown"],
      "description": "Issue classification type"
    },
    "confidence": {
      "type": "number",
      "description": "Confidence score between 0.0 and 1.0 (must be < 0.8 for vague/ambiguous issues)"
    }
  },
  "required": ["type", "confidence"]
}

parameters.jsCode:
const item = $input.first().json;

let data = null;

// 1. Direct object check
if (item.type || item.classification || item.issue_type) {
  data = item;
} else if (item.output && typeof item.output === 'object') {
  data = item.output;
} else {
  // 2. Extract from string field (text, output, response)
  const raw = item.text || item.output || item.response || (typeof item === 'string' ? item : JSON.stringify(item));
  if (typeof raw === 'string') {
    const cleaned = raw.replace(/```(?:json)?\s*([\s\S]*?)\s*```/g, '$1').trim();
    try {
      data = JSON.parse(cleaned);
    } catch (e) {
      const typeM = cleaned.match(/"(?:type|classification|issue_type|category)"\s*:\s*"([^"]+)"/i);
      const confM = cleaned.match(/"confidence"\s*:\s*([0-9.]+)/i);
      data = {
        type: typeM ? typeM[1] : 'unknown',
        confidence: confM ? parseFloat(confM[1]) : 0.5
      };
    }
  }
}

if (!data) data = {};

const rawType = data.type || data.classification || data.issue_type || data.category || 'unknown';
const cleanType = String(rawType).toLowerCase().trim();

let conf = 0.5;
if (typeof data.confidence === 'number') {
  conf = data.confidence;
} else if (data.confidence !== undefined) {
  conf = parseFloat(data.confidence) || 0.5;
}

return [{
  json: {
    type: cleanType,
    confidence: conf
  }
}];
